window.AUTH=window.AUTH||{};window.AUTH["22-1165"]={"d":"22-1165","id":"2023/22-1165","n":"Macquarie Infrastructure Corp. v. Moab Partners, L.P.","briefs":[{"k":"petitioner","label":"Brief of petitioners Macquarie Infrastructure Corp., et al.","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/289407/20231113141216216_MIC%20Opening%20Merits%20Brief%20-%20PRINT%20PDFA.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent Barclays Capital Inc. in support of vacatur","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/289445/20231113155738638_22-1165_brief.pdf","side":"res","n":11},{"k":"respondent","label":"Brief of respondent Moab Partners, L.P.","date":"2023-12-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/293313/20231213162158729_Moab%20brief.pdf","side":"res","n":89},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-12-20","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/293867/20231220141226444_22-1165ac%20Macquarie%20v.%20Moab%20Partners.pdf","side":"us","n":52},{"k":"reply","label":"Reply of petitioners Macquarie Infrastructure Corp., et al.","date":"2024-01-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-1165/295031/20240105132016708_MIC%20Merits%20Reply%20Brief%2022-1165%20-%20PRINT%20PDFA.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r13_8mjp.pdf","tr":true,"items":[{"t":"case","label":"Affiliated Ute Citizens of Utah v. United States","cite":"406 U.S. 128","y":1972,"id":"1971/70-78","sc":1,"by":{"0":"23","2":"19","4":"10"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"0":"38, 39"},"q":[{"src":"brief","b":0,"text":"If the statute itself does not ‘displa[y] an intent’ to create ‘a private remedy,’ then ‘a cause of action does not exist and courts may not create one, no matter how desirable that might be as a policy matter’","cite":"532 U.S. at 286"},{"src":"brief","b":0,"text":"accept [an] invitation to have one last drink.","cite":"532 U.S. at 287"}]},{"t":"case","label":"Basic Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"by":{"0":"10, 22, 33","2":"2, 4, 25-27, 35, 42-45, 47, 26, 37","3":"13, 18, 22, 26","4":"7, 12, 13, 21"},"q":[{"src":"brief","b":2,"text":"filter[s] out essentially useless information that a reasonable investor would not consider significant,","cite":"485 U.S. at 234"},{"src":"brief","b":2,"text":"Disclosure, and not paternalistic withholding of accurate information, is the policy chosen and expressed by Congress.","cite":"485 U.S. at 234"},{"src":"brief","b":3,"text":"Silence, absent a duty to disclose, is not misleading under Rule 10b-5.","cite":"485 U.S. at 239 n.17"},{"src":"brief","b":4,"text":"[s]ilence, absent a duty to disclose, is not misleading under Rule 10b-5.","cite":"485 U.S. 224, 239 n.17"},{"src":"argument","who":"Justice Thomas","text":"We're saying that it has -- there has to be an Item 3 -- Item 303 violation, it has to be material under this Court's decision in Basic, which is a different materiality standard than Item 303 itself, and then there has to be scienter as well."},{"src":"argument","who":"Justice Kavanaugh","text":"McDOWELL: Once you have that, then you would also have to show materiality under Basic, which is oftentimes a higher threshold, as well as scienter."}]},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"by":{"0":"7, 26, 31","1":"8","2":"32"},"q":[{"src":"brief","b":0,"text":"had little trouble in doing so expressly.","cite":"421 U.S. at 734"}]},{"t":"case","label":"Carvelli v. Ocwen Fin. Corp.","cite":"934 F.3d 1307","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/1307/","by":{"0":"29, 41"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"0":"6, 7, 38","1":"8","2":"35"},"q":[{"src":"brief","b":2,"text":"would put an unsupportable interpretation on Congress’ specific response","cite":"511 U.S. 164"}]},{"t":"case","label":"Chadbourne & Parke LLP v. Troice","cite":"571 U.S. 377","y":2014,"id":"2013/12-79","sc":1,"by":{"0":"32","4":"7"},"q":[{"src":"brief","b":4,"text":"[t]he scope of the private right of action is more limited than the scope of the statutes upon which it is based.","cite":"571 U.S. 377, 382"}]},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"by":{"0":"22, 23","2":"15, 21, 23-24","3":"2, 8, 19, 22, 29","4":"10, 13"},"q":[{"src":"brief","b":0,"text":"Section 10(b) is aptly described as a catchall provision, but what it catches must be fraud.","cite":"445 U.S. at 234"},{"src":"brief","b":2,"text":"a catch-all clause to prevent fraudulent practices.","cite":"445 U.S. 222, 226"},{"src":"brief","b":2,"text":"when he is under a duty to do so.","cite":"445 U.S. at 227"},{"src":"brief","b":3,"text":"Section 10(b) is aptly described as a catchall","cite":"445 U.S. 222, 234-235"},{"src":"brief","b":3,"text":"under a duty to * * * disclose.","cite":"445 U.S. 222, 228"}]},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"by":{"0":"5, 6, 26","2":"16, 31","3":"3, 31, 32","4":"6"},"q":[{"src":"brief","b":3,"text":"impose[s] regular reporting requirements on companies whose stock is listed on national securities exchanges.","cite":"425 U.S. 185, 195"}]},{"t":"case","label":"Goldman Sachs Grp., Inc. v. Ark. Tchr. Ret. Sys.","cite":"141 S. Ct. 1951","y":2021,"id":"2020/20-222","sc":1,"by":{"0":"37","2":"21","3":"1","4":"10"}},{"t":"case","label":"Ind. Pub. Ret. Sys. v. SAIC, Inc.","cite":"818 F.3d 85","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/818/85/","by":{"0":"14"}},{"t":"case","label":"Janus Cap. Grp., Inc. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"by":{"0":"8, 20, 22, 34","2":"36, 40","4":"2, 12, 13"},"q":[{"src":"brief","b":0,"text":"mindful that [it] must give ‘narrow dimensions * * * to a right of action Congress did not authorize when it first enacted the statute and did not expand when it revisited the law.’","cite":"564 U.S. at 142"},{"src":"argument","who":"Chief Justice Roberts","text":"The other thing I would say about this is I think Petitioners are over-reading this Court's decisions in Stoneridge and Janus. We read those decisions to reject attempts to expand the class of defendants who can be liable under Rule 10b-5 after the PSLRA."}]},{"t":"case","label":"Kokesh v. Sec. & Exch. Comm’n","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"by":{"0":"29","2":"2"},"q":[{"src":"brief","b":0,"text":"a full panoply of enforcement tools.","cite":"581 U.S. 455, 459"}]},{"t":"case","label":"Litwin v. Blackstone Grp., L.P.","cite":"634 F.3d 706","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/634/706/","by":{"0":"27, 28","1":"3, 4, 8","4":"4"}},{"t":"case","label":"Lorenzo v. Sec. & Exch. Comm’n","cite":"139 S. Ct. 1094","y":2019,"id":"2018/17-1077","sc":1,"by":{"0":"23, 24","2":"18-19, 33-34","3":"20-24, 32, 34","4":"10, 11"},"q":[{"src":"brief","b":2,"text":"These provisions capture a wide range of conduct.","cite":"139 S. Ct. 1094, 1101"},{"src":"brief","b":2,"text":"is simply ‘that which is devised, or formed by design’; a ‘scheme’ is a ‘project,’ ‘plan, or program of something to be done’; and an ‘artifice’ is ‘an artful stratagem or trick.’","cite":"139 S. Ct. at 1101"},{"src":"brief","b":3,"text":"‘device’ * * * is simply ‘[t]hat which is devised or formed by design’; a ‘scheme’ is a ‘project,’ ‘plan[,] or program of something to be done’; and an ‘artifice’ is ‘an artful stratagem or trick.’","cite":"139 S. Ct. 1094, 1101"},{"src":"brief","b":3,"text":"should be read as governing different, mutually exclusive, spheres of conduct.","cite":"139 S. Ct. at 1102"}]},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"by":{"0":"2, 21, 22, 28","2":"4, 22, 26-27, 45, 27","3":"22","4":"7"},"q":[{"src":"brief","b":0,"text":"necessary ‘to make * * * statements made, in the light of the circumstances under which they were made, not misleading.’","cite":"563 U.S. at 44"},{"src":"brief","b":0,"text":"to disclose any and all material information.","cite":"563 U.S. at 44"},{"src":"brief","b":2,"text":"a mental state embracing intent to deceive, manipulate, or defraud,","cite":"563 U.S. at 48"},{"src":"brief","b":2,"text":"intent to deceive, manipulate, or defraud,","cite":"563 U.S. at 48"},{"src":"brief","b":3,"text":"create an affirmative duty to disclose any and all material information.","cite":"563 U.S. 27, 45"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"bears emphasis that § 10(b) and Rule 10b–5(b) do not create an affrmative duty to disclose any and all material information. Disclosure is required under these provisions only when necessary `to make . . . statements made, in the light of the circumstances under which they were made, not misleading.'","cite":"563 U. S. 27, 44"}]},{"t":"case","label":"McCarthy v. Bronson","cite":"500 U.S. 136","y":1991,"id":"1990/90-5635","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"the language and design of the statute as a whole.","cite":"500 U.S. 136, 139"}]},{"t":"case","label":"Omnicare, Inc. v. Laborers Dist. Council Constr. Indus. Pension Fund","cite":"575 U.S. 175","y":2015,"id":"2014/13-435","sc":1,"by":{"0":"36, 44","2":"16-18, 21, 27-28","3":"10","4":"7, 15, 17, 20, 21"},"q":[{"src":"brief","b":2,"text":"as a class are formal documents, filed with the SEC","cite":"575 U.S. at 190"},{"src":"brief","b":2,"text":"literal accuracy is not enough: An issuer must as well desist from misleading investors by saying one thing and holding back another.","cite":"575 U.S. at 192"},{"src":"brief","b":3,"text":"[t]he reasonable investor understands a statement * * * in its full context.","cite":"575 U.S. 175, 186-187, 190"},{"src":"argument","who":"Ms. Coberly","text":"It might also invoke this Court's ruling in Omnicare, which identifies statements of opinion as being different from statements of fact. Now, of course, a statement of opinion can be misleading, but that requires a very special kind of omitted fact that the Court was very clear about in the Omnicare decision."}]},{"t":"case","label":"Oran v. Stafford","cite":"226 F.3d 275","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/226/275/","by":{"0":"29, 42","2":"42-44","3":"19, 26, 27","4":"21"},"q":[{"src":"brief","b":4,"text":"varies considerably from the general test for securities fraud materiality set out by the Supreme Court in Basic.","cite":"226 F.3d 275, 288"}]},{"t":"case","label":"Panther Partners Inc. v. Ikanos Commc’ns, Inc.","cite":"681 F.3d 114","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/681/114/","by":{"0":"27, 28","1":"3, 8","4":"4"},"q":[{"src":"brief","b":0,"text":"contain[s] an untrue statement of a material fact or omit[s] to state a material fact required to be stated therein or necessary to make the statements therein not misleading.","cite":"681 F.3d at 120"},{"src":"brief","b":0,"text":"imposes liability under similar circumstances [to § 11] for misstatements or omissions in a prospectus","cite":"681 F.3d at 120"}]},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"a specific provision * * * is swallowed by the general one.","cite":"566 U.S. at 645"}]},{"t":"case","label":"viii Salman v. United States","cite":"580 U.S. 39","y":2016,"url":"https://supreme.justia.com/cases/federal/us/580/39/","sc":1,"by":{"0":"23"}},{"t":"case","label":"Santa Fe Indus. v. Green","cite":"430 U.S. 462","y":1977,"id":"1976/75-1753","sc":1,"by":{"0":"38","2":"16"}},{"t":"case","label":"Sec. & Exch. Comm’n v. McNulty","cite":"137 F.3d 732","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/137/732/","by":{"0":"8"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Rio Tinto plc","cite":"41 F.4th 47","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/41/47/","by":{"0":"24","4":"11"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Ronson Corp.","cite":"1983 WL 1357","y":1983,"court":"D.N.J. Aug. 15","by":{"0":"45"}},{"t":"case","label":"Sec. & Exch. Comm’n v. Teo","cite":"746 F.3d 90","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/746/90/","by":{"0":"8"}},{"t":"case","label":"Slack Techs., LLC v. Pirani","cite":"598 U.S. 759","y":2023,"id":"2022/22-200","sc":1,"by":{"0":"20, 25","2":"2"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Sci.Atl., Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"by":{"0":"2, 8, 20, 22, 31, 38, 39","1":"2","2":"3, 18, 35-36","3":"2, 29, 30","4":"7, 11, 12, 13"},"q":[{"src":"brief","b":0,"text":"accepted the § 10(b) private cause of action as then defined but chose to extend it no further.","cite":"552 U.S. at 166"},{"src":"brief","b":2,"text":"a specific oral or written statement.","cite":"552 U.S. at 158"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"has found a right of action implied in the words of [§ 10(b)] and its implementing regulation.","cite":"552 U. S. 148, 157"},{"src":"argument","who":"Chief Justice Roberts","text":"The other thing I would say about this is I think Petitioners are over-reading this Court's decisions in Stoneridge and Janus. We read those decisions to reject attempts to expand the class of defendants who can be liable under Rule 10b-5 after the PSLRA."}]},{"t":"case","label":"Stratte-McClure v. Morgan Stanley","cite":"776 F.3d 94","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/776/94/","by":{"0":"14, 28, 35","1":"3, 7, 8","2":"12, 42,44","3":"19, 26, 33","4":"4, 5, 6"},"q":[{"src":"brief","b":0,"text":"d[id] not ‘allege that’ any ‘omitted information was material’ under the relevant ‘probability/magnitude test’ for assessing Item 303 violations.","cite":"776 F.3d 94, 103"},{"src":"brief","b":0,"text":"adequately alleged a ‘known trend[] or uncertaint[y]’ that gave rise to a duty to disclose under Item 303.","cite":"776 F.3d at 101"},{"src":"brief","b":1,"text":"both make unlawful omission of ‘material fact[s] * * * necessary in order to make * * * statements, in light of the circumstances under which they were made, not misleading.’","cite":"776 F.3d 94, 104"},{"src":"brief","b":1,"text":"issuing financial statements that omit elements required by Item 303 can mislead investors.","cite":"776 F.3d at 104"},{"src":"argument","who":"Mr. Frederick","text":"And I would point out that the underlying Second Circuit case that's really on appeal here is called Stratte-McClure. That was the precedent on which the per curiam panel below relied."},{"src":"argument","who":"Mr. Frederick","text":"What the Stratte-McClure Court said and held was that the omissions rendered the financial statement misleading. And so the Second Circuit has viewed the categorical position that the government does as the correct ruling on the statement."},{"src":"argument","who":"Justice Jackson","text":"And I read it to basically cite and adopt the Second Circuit's precedential opinion on this issue, which is Stratte-McClure. And Stratte-McClure does rely on, as I read it, a half-truths theory because it says that the -- an Item 303 violation renders the financial statement misleading, which I take to mean the MD&A, and that's exactly our position."}]},{"t":"case","label":"Superintendent of Ins. v. Bankers Life & Cas. Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"by":{"0":"7"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rts., Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"by":{"0":"8","2":"7, 44-45, 47","3":"5, 28"},"q":[{"src":"brief","b":2,"text":"plead facts rendering an inference of scienter at least as likely as any plausible opposing inference.","cite":"551 U.S. at 328"},{"src":"brief","b":3,"text":"intent to deceive, manipulate, or defraud.","cite":"551 U.S. at 319"}]},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"by":{"0":"6, 7, 31, 32","2":"31","3":"32"},"q":[{"src":"brief","b":0,"text":"principal express civil remedy for misstatements in reports.","cite":"442 U.S. 560, 574"},{"src":"brief","b":0,"text":"extremely reluctant to imply a cause of action * * * that is significantly broader than the remedy that Congress chose to provide.","cite":"442 U.S. at 574"}]},{"t":"case","label":"ix United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"by":{"0":"21, 23","2":"19, 24","3":"19, 21","4":"10"}},{"t":"case","label":"Universal Health Servs. v. United States ex rel. Escobar","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"by":{"0":"19, 33, 39","2":"17, 22-23, 29, 39-40, 45","3":"10, 11, 14, 15, 17, 18, 29","4":"17, 18"},"q":[{"src":"brief","b":2,"text":"impliedly certifies compliance with all conditions of payment","cite":"579 U.S. at 180"},{"src":"brief","b":3,"text":"representations that state the truth only so far as it goes, while omitting critical qualifying information.","cite":"579 U.S. 176, 188"}]},{"t":"case","label":"Va. Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"by":{"0":"39"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"by":{"0":"20"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"0":"38"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 77j","url":"https://www.law.cornell.edu/uscode/text/15/77j","subs":["(c)"],"by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(a)","(e)"],"stext":{"head":"§77k. Civil liabilities on account of false registration statement","paras":[[0,"(a) Persons possessing cause of action; persons liable"],[0,"In case any part of the registration statement, when such part became effective, contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading, any person acquiring such security (unless it is proved that at the time of such acquisition he knew of such untruth or omission) may, either at law or in equity, in any court of competent jurisdiction, sue—"],[1,"(1) every person who signed the registration statement;"],[1,"(2) every person who was a director of (or person performing similar functions) or partner in the issuer at the time of the filing of the part of the registration statement with respect to which his liability is asserted;"],[1,"(3) every person who, with his consent, is named in the registration statement as being or about to become a director, person performing similar functions, or partner;"],[1,"(4) every accountant, engineer, or appraiser, or any person whose profession gives authority to a statement made by him, who has with his consent been named as having prepared or certified any part of the registration statement, or as having prepared or certified any report or valuation which is used in connection with the registration statement, with respect to the statement in such registration statement, report, or valuation, which purports to have been prepared or certified by him;"],[1,"(5) every underwriter with respect to such security."],[0,"If such person acquired the security after the issuer has made generally available to its security holders an earning statement covering a period of at least twelve months beginning after the effective date of the registration statement, then the right of recovery under this subsection shall be conditioned on proof that such person acquired the security relying upon such untrue statement in the registration statement or relying upon the registration statement and not knowing of such omission, but such reliance may be established without proof of the reading of the registration statement by such person."],[0,"(b) Persons exempt from liability upon proof of issues"],[0,"Notwithstanding the provisions of subsection (a) no person, other than the issuer, shall be liable as provided therein who shall sustain the burden of proof—"],[1,"(1) that before the effective date of the part of the registration statement with respect to which his liability is asserted (A) he had resigned from or had taken such steps as are permitted by law to resign from, or ceased or refused to act in, every office, capacity, or relationship in which he was described in the registration statement as acting or agreeing to act, and (B) he had advised the Commission and the issuer in writing that he had taken such action and that he would not be responsible for such part of the registration statement; or"],[1,"(2) that if such part of the registration statement became effective without his knowledge, upon becoming aware of such fact he forthwith acted and advised the Commission, in accordance with paragraph (1) of this subsection, and, in addition, gave reasonable public notice that such part of the registration statement had become effective without his knowledge; or"],[1,"(3) that (A) as regards any part of the registration statement not purporting to be made on the authority of an expert, and not purporting to be a copy of or extract from a report or valuation of an expert, and not purporting to be made on the authority of a public official document or statement, he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading; and (B) as regards any part of the registration statement purporting to be made upon his authority as an expert or purporting to be a copy of or extract from a report or valuation of himself as an expert, (i) he had, after reasonable investigation, reasonable ground to believe and did believe, at the time such part of the registration statement became effective, that the statements therein were true and that there was no omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or (ii) such part of the registration statement did not fairly represent his statement as an expert or was not a fair copy of or extract from his report or valuation as an expert; and (C) as regards any part of the registration statement purporting to be made on the authority of an expert (other than himself) or purporting to be a copy of or extract from a report or valuation of an expert (other than himself), he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement of the expert or was not a fair copy of or extract from the report or valuation of the expert; and (D) as regards any part of the registration statement purporting to be a statement made by an official person or purporting to be a copy of or extract from a public official document, he had no reasonable ground to believe and did not believe, at the time such part of the registration statement became effective, that the statements therein were untrue, or that there was an omission to state a material fact required to be stated therein or necessary to make the statements therein not misleading, or that such part of the registration statement did not fairly represent the statement made by the official person or was not a fair copy of or extract from the public official document."],[0,"(c) Standard of reasonableness"],[0,"In determining, for the purpose of paragraph (3) of subsection (b) of this section, what constitutes reasonable investigation and reasonable ground for belief, the standard of reasonableness shall be that required of a prudent man in the management of his own property."],[0,"(d) Effective date of registration statement with regard to underwriters"],[0,"If any person becomes an underwriter with respect to the security after the part of the registration statement with respect to which his liability is asserted has become effective, then for the purposes of paragraph (3) of subsection (b) of this section such part of the registration statement shall be considered as having become effective with respect to such person as of the time when he became an underwriter."],[0,"(e) Measure of damages; undertaking for payment of costs"],[0,"The suit authorized under subsection (a) may be to recover such damages as shall represent the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and (1) the value thereof as of the time such suit was brought, or (2) the price at which such security shall have been disposed of in the market before suit, or (3) the price at which such security shall have been disposed of after suit but before judgment if such damages shall be less than the damages representing the difference between the amount paid for the security (not exceeding the price at which the security was offered to the public) and the value thereof as of the time such suit was brought: Provided, That if the defendant proves that any portion or all of such damages represents other than the depreciation in value of such security resulting from such part of the registration statement, with respect to which his liability is asserted, not being true or omitting to state a material fact required to be stated therein or necessary to make the statements therein not misleading, such portion of or all such damages shall not be recoverable. In no event shall any underwriter (unless such underwriter shall have knowingly received from the issuer for acting as an underwriter some benefit, directly or indirectly, in which all other underwriters similarly situated did not share in proportion to their respective interests in the underwriting) be liable in any suit or as a consequence of suits authorized under subsection (a) for damages in excess of the total price at which the securities underwritten by him and distributed to the public were offered to the public. In any suit under this or any other section of this subchapter the court may, in its discretion, require an undertaking for the payment of the costs of such suit, including reasonable attorney's fees, and if judgment shall be rendered against a party litigant, upon the motion of the other party litigant, such costs may be assessed in favor of such party litigant (whether or not such undertaking has been required) if the court believes the suit or the defense to have been without merit, in an amount sufficient to reimburse him for the reasonable expenses incurred by him, in connection with such suit, such costs to be taxed in the manner usually provided for taxing of costs in the court in which the suit was heard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77k?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 5, 13, 17, 18, 26, 27, 28, 34, 27","2":"11, 14, 21, 27, 30-33, 43-44, 48-49, 27, 30, 33","3":"30, 31","4":"4, 5, 6, 7, 8, 4, 5"},"q":[{"src":"brief","b":0,"text":"necessary to make the statements therein not misleading.","cite":"15 U.S.C. § 77k"},{"src":"brief","b":0,"text":"contained an untrue statement of a material fact or omitted to state a material fact required to be stated therein or necessary to make the statements therein not misleading.","cite":"15 U.S.C. § 77k"},{"src":"brief","b":2,"text":"to state a material fact . . . necessary to make the statements therein not misleading.","cite":"15 U.S.C. § 77k(a)"},{"src":"brief","b":4,"text":"manipulative or deceptive device or contrivance.","cite":"15 U.S.C. §77k"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"contain[s] an untrue statement of a material fact or omit[s] to state a material fact required to be stated therein or necessary to make the statements therein not misleading.","cite":"15 U. S. C. § 77k(a)"}]},{"t":"usc","label":"15 U.S.C. § 77l","url":"https://www.law.cornell.edu/uscode/text/15/77l","subs":["(a)(2)","(b)"],"by":{"0":"5, 13, 27, 5, 27","2":"33, 49, 11, 33, 48-49, 33","4":"4, 5, 4, 5"}},{"t":"usc","label":"15 U.S.C. § 77o","url":"https://www.law.cornell.edu/uscode/text/15/77o","by":{"0":"5, 13"}},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 4, 5, 6, 7, 20, 21, 22, 25, 26, 27, 29, 31, 38","2":"21, 31, 49, 1-4, 11-16, 24, 28, 30-31, 35-37, 41-47","3":"3","4":"6, 7, 8, 17"},"q":[{"src":"brief","b":0,"text":"[t]o use or employ, in connection with the purchase or sale of any security * * * any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe.","cite":"15 U.S.C. § 78j(b)"},{"src":"brief","b":2,"text":"in connection with the purchase or sale of any security.","cite":"15 U.S.C. § 78j(b)"},{"src":"brief","b":2,"text":"rules and regulations [of ] the Commission,","cite":"15 U.S.C. § 78j(b)"},{"src":"brief","b":3,"text":"[t]o use or employ, in connection with the purchase or sale of any security[,] * * * any manipulative or deceptive device or contrivance in contravention of","cite":"15 U.S.C. 78j(b)"},{"src":"brief","b":3,"text":"any manipulative or deceptive device or contrivance in contravention of","cite":"15 U.S.C. 78j(b)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"unlawful for any person . . . [t]o use or employ, in connection with the purchase or sale of any security . . . , any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the [SEC] may prescribe.","cite":"15 U. S. C. § 78j(b)"}]},{"t":"usc","label":"15 U.S.C. § 78m","url":"https://www.law.cornell.edu/uscode/text/15/78m","subs":["(a)","(a)(2)","(a)(1)"],"stext":{"head":"§78m. Periodical and other reports","paras":[[0,"(a) Reports by issuer of security; contents"],[0,"Every issuer of a security registered pursuant to section 78l of this title shall file with the Commission, in accordance with such rules and regulations as the Commission may prescribe as necessary or appropriate for the proper protection of investors and to insure fair dealing in the security—"],[1,"(1) such information and documents (and such copies thereof) as the Commission shall require to keep reasonably current the information and documents required to be included in or filed with an application or registration statement filed pursuant to section 78l of this title, except that the Commission may not require the filing of any material contract wholly executed before July 1, 1962."],[1,"(2) such annual reports (and such copies thereof), certified if required by the rules and regulations of the Commission by independent public accountants, and such quarterly reports (and such copies thereof), as the Commission may prescribe."],[0,"Every issuer of a security registered on a national securities exchange shall also file a duplicate original of such information, documents, and reports with the exchange. In any registration statement, periodic report, or other reports to be filed with the Commission, an emerging growth company need not present selected financial data in accordance with section 229.301 of title 17, Code of Federal Regulations, for any period prior to the earliest audited period presented in connection with its first registration statement that became effective under this chapter or the Securities Act of 1933 [15 U.S.C. 77a et seq.] and, with respect to any such statement or reports, an emerging growth company may not be required to comply with any new or revised financial accounting standard until such date that a company that is not an issuer (as defined under section 7201 of this title) is required to comply with such new or revised accounting standard, if such standard applies to companies that are not issuers."],[0,"(b) Form of report; books, records, and internal accounting; directives"],[0,"(1) The Commission may prescribe, in regard to reports made pursuant to this chapter, the form or forms in which the required information shall be set forth, the items or details to be shown in the balance sheet and the earnings statement, and the methods to be followed in the preparation of reports, in the appraisal or valuation of assets and liabilities, in the determination of depreciation and depletion, in the differentiation of recurring and nonrecurring income, in the differentiation of investment and operating income, and in the preparation, where the Commission deems it necessary or desirable, of separate and/or consolidated balance sheets or income accounts of any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer; but in the case of the reports of any person whose methods of accounting are prescribed under the provisions of any law of the United States, or any rule or regulation thereunder, the rules and regulations of the Commission with respect to reports shall not be inconsistent with the requirements imposed by such law or rule or regulation in respect of the same subject matter (except that such rules and regulations of the Commission may be inconsistent with such requirements to the extent that the Commission determines that the public interest or the protection of investors so requires)."],[0,"(2) Every issuer which has a class of securities registered pursuant to section 78l of this title and every issuer which is required to file reports pursuant to section 78o(d) of this title shall—"],[1,"(A) make and keep books, records, and accounts, which, in reasonable detail, accurately and fairly reflect the transactions and dispositions of the assets of the issuer;"],[1,"(B) devise and maintain a system of internal accounting controls sufficient to provide reasonable assurances that—"],[2,"(i) transactions are executed in accordance with management's general or specific authorization;"],[2,"(ii) transactions are recorded as necessary (I) to permit preparation of financial statements in conformity with generally accepted accounting principles or any other criteria applicable to such statements, and (II) to maintain accountability for assets;"],[2,"(iii) access to assets is permitted only in accordance with management's general or specific authorization; and"],[2,"(iv) the recorded accountability for assets is compared with the existing assets at reasonable intervals and appropriate action is taken with respect to any differences; and"],[1,"(C) notwithstanding any other provision of law, pay the allocable share of such issuer of a reasonable annual accounting support fee or fees, determined in accordance with section 7219 of this title."],[0,"(3)(A) With respect to matters concerning the national security of the United States, no duty or liability under paragraph (2) of this subsection shall be imposed upon any person acting in cooperation with the head of any Federal department or agency responsible for such matters if such act in cooperation with such head of a department or agency was done upon the specific, written directive of the head of such department or agency pursuant to Presidential authority to issue such directives. Each directive issued under this paragraph shall set forth the specific facts and circumstances with respect to which the provisions of this paragraph are to be invoked. Each such directive shall, unless renewed in writing, expire one year after the date of issuance."],[0,"(B) Each head of a Federal department or agency of the United States who issues a directive pursuant to this paragraph shall maintain a complete file of all such directives and shall, on October 1 of each year, transmit a summary of matters covered by such directives in force at any time during the previous year to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate."],[0,"(4) No criminal liability shall be imposed for failing to comply with the requirements of paragraph (2) of this subsection except as provided in paragraph (5) of this subsection."],[0,"(5) No person shall knowingly circumvent or knowingly fail to implement a system of internal accounting controls or knowingly falsify any book, record, or account described in paragraph (2)."],[0,"(6) Where an issuer which has a class of securities registered pursuant to section 78l of this title or an issuer which is required to file reports pursuant to section 78o(d) of this title holds 50 per centum or less of the voting power with respect to a domestic or foreign firm, the provisions of paragraph (2) require only that the issuer proceed in good faith to use its influence, to the extent reasonable under the issuer's circumstances, to cause such domestic or foreign firm to devise and maintain a system of internal accounting controls consistent with paragraph (2). Such circumstances include the relative degree of the issuer's ownership of the domestic or foreign firm and the laws and practices governing the business operations of the country in which such firm is located. An issuer which demonstrates good faith efforts to use such influence shall be conclusively presumed to have complied with the requirements of paragraph (2)."],[0,"(7) For the purpose of paragraph (2) of this subsection, the terms \"reasonable assurances\" and \"reasonable detail\" mean such level of detail and degree of assurance as would satisfy prudent officials in the conduct of their own affairs."],[0,"(c) Alternative reports"],[0,"If in the judgment of the Commission any report required under subsection (a) is inapplicable to any specified class or classes of issuers, the Commission shall require in lieu thereof the submission of such reports of comparable character as it may deem applicable to such class or classes of issuers."],[0,"(d) Reports by persons acquiring more than five per centum of certain classes of securities"],[0,"(1) Any person who, after acquiring directly or indirectly the beneficial ownership of any equity security of a class which is registered pursuant to section 78l of this title, or any equity security of an insurance company which would have been required to be so registered except for the exemption contained in section 78l(g)(2)(G) of this title, or any equity security issued by a closed-end investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.] or any equity security issued by a Native Corporation pursuant to section 1629c(d)(6) of title 43, or otherwise becomes or is deemed to become a beneficial owner of any of the foregoing upon the purchase or sale of a security-based swap that the Commission may define by rule, and is directly or indirectly the beneficial owner of more than 5 per centum of such class shall, within ten days after such acquisition or within such shorter time as the Commission may establish by rule, file with the Commission, a statement containing such of the following information, and such additional information, as the Commission may by rules and regulations, prescribe as necessary or appropriate in the public interest or for the protection of investors—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78m?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 6, 8, 16, 35","2":"4, 17, 20, 26, 39, 41, 9, 16-17, 29, 39, 46, 4, 39","3":"2, 3, 5, 12, 3","4":"9, 15"},"q":[{"src":"brief","b":3,"text":"such information * * * as the Commission shall require,","cite":"15 U.S.C. 78m(a)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"in accordance with such rules and regulations as the Commission may prescribe,","cite":"15 U. S. C. § 78m(a)"}]},{"t":"usc","label":"15 U.S.C. § 78r","url":"https://www.law.cornell.edu/uscode/text/15/78r","subs":["(a)"],"stext":{"head":"§78r. Liability for misleading statements","paras":[[0,"(a) Persons liable; persons entitled to recover; defense of good faith; suit at law or in equity; costs, etc."],[0,"Any person who shall make or cause to be made any statement in any application, report, or document filed pursuant to this chapter or any rule or regulation thereunder or any undertaking contained in a registration statement as provided in subsection (d) of section 78o of this title, which statement was at the time and in the light of the circumstances under which it was made false or misleading with respect to any material fact, shall be liable to any person (not knowing that such statement was false or misleading) who, in reliance upon such statement, shall have purchased or sold a security at a price which was affected by such statement, for damages caused by such reliance, unless the person sued shall prove that he acted in good faith and had no knowledge that such statement was false or misleading. A person seeking to enforce such liability may sue at law or in equity in any court of competent jurisdiction. In any such suit the court may, in its discretion, require an undertaking for the payment of the costs of such suit, and assess reasonable costs, including reasonable attorneys' fees, against either party litigant."],[0,"(b) Contribution"],[0,"Every person who becomes liable to make payment under this section may recover contribution as in cases of contract from any person who, if joined in the original suit, would have been liable to make the same payment."],[0,"(c) Period of limitations"],[0,"No action shall be maintained to enforce any liability created under this section unless brought within one year after the discovery of the facts constituting the cause of action and within three years after such cause of action accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78r?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 17, 6, 17, 25, 30, 31","2":"31","3":"32, 32","4":"8"},"q":[{"src":"brief","b":0,"text":"false or misleading with respect to any material fact.","cite":"15 U.S.C. § 78r(a)"},{"src":"brief","b":3,"text":"in any application, report, or document filed pursuant to","cite":"15 U.S.C. 78r(a)"}]},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(a)"],"by":{"0":"5, 13"}},{"t":"usc","label":"15 U.S.C. § 78t-1","url":"https://www.law.cornell.edu/uscode/text/15/78t-1","by":{"0":"5, 13","2":"11"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(a)(1)","(d)(1)","(d)(3)","(d)(5)","(d)(7)","(d)(2)"],"by":{"0":"29, 29, 30, 30, 30, 30","3":"33"},"q":[{"src":"brief","b":0,"text":"specify each statement alleged to have been misleading","cite":"15 U.S.C. § 78u"},{"src":"brief","b":0,"text":"specify each statement alleged to have been misleading [and] the reason or reasons why the statement is misleading.","cite":"15 U.S.C. § 78u"},{"src":"brief","b":3,"text":"specify each statement alleged to have been misleading,","cite":"15 U.S.C. 78u"},{"src":"brief","b":3,"text":"with particularity facts giving rise to a strong inference that the defendant acted with the required state of mind.","cite":"15 U.S.C. 78u"}]},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","subs":["(a)(2)"],"by":{"0":"8","3":"3, 33"},"q":[{"src":"brief","b":3,"text":"has the power to enforce disclosure requirements","cite":"15 U.S.C. 78u-2"}]},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","subs":["(a)"],"by":{"0":"8"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"2, 5, 7, 8, 18, 31, 32, 38","2":"3, 14, 29, 33, 35-38, 45","3":"16","4":"5"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(1)","(b)(3)(A)","(b)(4)","(b)(2)","(f)(10)(A)(i)","(b)(2)(A)","(f)(10)(A)(i)(I)","(f)(10)(A)(ii)"],"stext":{"head":"§78u–4. Private securities litigation","paras":[[0,"(a) Private class actions"],[0,"(1) In general"],[1,"The provisions of this subsection shall apply in each private action arising under this chapter that is brought as a plaintiff class action pursuant to the Federal Rules of Civil Procedure."],[0,"(2) Certification filed with complaint"],[0,"(A) In general"],[2,"Each plaintiff seeking to serve as a representative party on behalf of a class shall provide a sworn certification, which shall be personally signed by such plaintiff and filed with the complaint, that—"],[3,"(i) states that the plaintiff has reviewed the complaint and authorized its filing;"],[3,"(ii) states that the plaintiff did not purchase the security that is the subject of the complaint at the direction of plaintiff's counsel or in order to participate in any private action arising under this chapter;"],[3,"(iii) states that the plaintiff is willing to serve as a representative party on behalf of a class, including providing testimony at deposition and trial, if necessary;"],[3,"(iv) sets forth all of the transactions of the plaintiff in the security that is the subject of the complaint during the class period specified in the complaint;"],[3,"(v) identifies any other action under this chapter, filed during the 3-year period preceding the date on which the certification is signed by the plaintiff, in which the plaintiff has sought to serve as a representative party on behalf of a class; and"],[3,"(vi) states that the plaintiff will not accept any payment for serving as a representative party on behalf of a class beyond the plaintiff's pro rata share of any recovery, except as ordered or approved by the court in accordance with paragraph (4)."],[0,"(B) Nonwaiver of attorney-client privilege"],[2,"The certification filed pursuant to subparagraph (A) shall not be construed to be a waiver of the attorney-client privilege."],[0,"(3) Appointment of lead plaintiff"],[0,"(A) Early notice to class members"],[0,"(i) In general"],[3,"Not later than 20 days after the date on which the complaint is filed, the plaintiff or plaintiffs shall cause to be published, in a widely circulated national business-oriented publication or wire service, a notice advising members of the purported plaintiff class—"],[4,"(I) of the pendency of the action, the claims asserted therein, and the purported class period; and"],[4,"(II) that, not later than 60 days after the date on which the notice is published, any member of the purported class may move the court to serve as lead plaintiff of the purported class."],[0,"(ii) Multiple actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter is filed, only the plaintiff or plaintiffs in the first filed action shall be required to cause notice to be published in accordance with clause (i)."],[0,"(iii) Additional notices may be required under Federal rules"],[3,"Notice required under clause (i) shall be in addition to any notice required pursuant to the Federal Rules of Civil Procedure."],[0,"(B) Appointment of lead plaintiff"],[0,"(i) In general"],[3,"Not later than 90 days after the date on which a notice is published under subparagraph (A)(i), the court shall consider any motion made by a purported class member in response to the notice, including any motion by a class member who is not individually named as a plaintiff in the complaint or complaints, and shall appoint as lead plaintiff the member or members of the purported plaintiff class that the court determines to be most capable of adequately representing the interests of class members (hereafter in this paragraph referred to as the \"most adequate plaintiff\") in accordance with this subparagraph."],[0,"(ii) Consolidated actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter has been filed, and any party has sought to consolidate those actions for pretrial purposes or for trial, the court shall not make the determination required by clause (i) until after the decision on the motion to consolidate is rendered. As soon as practicable after such decision is rendered, the court shall appoint the most adequate plaintiff as lead plaintiff for the consolidated actions in accordance with this paragraph."],[0,"(iii) Rebuttable presumption"],[0,"(I) In general"],[4,"Subject to subclause (II), for purposes of clause (i), the court shall adopt a presumption that the most adequate plaintiff in any private action arising under this chapter is the person or group of persons that—"],[5,"(aa) has either filed the complaint or made a motion in response to a notice under subparagraph (A)(i);"],[5,"(bb) in the determination of the court, has the largest financial interest in the relief sought by the class; and"],[5,"(cc) otherwise satisfies the requirements of Rule 23 of the Federal Rules of Civil Procedure."],[0,"(II) Rebuttal evidence"],[4,"The presumption described in subclause (I) may be rebutted only upon proof by a member of the purported plaintiff class that the presumptively most adequate plaintiff—"],[5,"(aa) will not fairly and adequately protect the interests of the class; or"],[5,"(bb) is subject to unique defenses that render such plaintiff incapable of adequately representing the class."],[0,"(iv) Discovery"],[3,"For purposes of this subparagraph, discovery relating to whether a member or members of the purported plaintiff class is the most adequate plaintiff may be conducted by a plaintiff only if the plaintiff first demonstrates a reasonable basis for a finding that the presumptively most adequate plaintiff is incapable of adequately representing the class."],[0,"(v) Selection of lead counsel"],[3,"The most adequate plaintiff shall, subject to the approval of the court, select and retain counsel to represent the class."],[0,"(vi) Restrictions on professional plaintiffs"],[3,"Except as the court may otherwise permit, consistent with the purposes of this section, a person may be a lead plaintiff, or an officer, director, or fiduciary of a lead plaintiff, in no more than 5 securities class actions brought as plaintiff class actions pursuant to the Federal Rules of Civil Procedure during any 3-year period."],[0,"(4) Recovery by plaintiffs"],[1,"The share of any final judgment or of any settlement that is awarded to a representative party serving on behalf of a class shall be equal, on a per share basis, to the portion of the final judgment or settlement awarded to all other members of the class. Nothing in this paragraph shall be construed to limit the award of reasonable costs and expenses (including lost wages) directly relating to the representation of the class to any representative party serving on behalf of a class."],[0,"(5) Restrictions on settlements under seal"],[1,"The terms and provisions of any settlement agreement of a class action shall not be filed under seal, except that on motion of any party to the settlement, the court may order filing under seal for those portions of a settlement agreement as to which good cause is shown for such filing under seal. For purposes of this paragraph, good cause shall exist only if publication of a term or provision of a settlement agreement would cause direct and substantial harm to any party."],[0,"(6) Restrictions on payment of attorneys' fees and expenses"],[1,"Total attorneys' fees and expenses awarded by the court to counsel for the plaintiff class shall not exceed a reasonable percentage of the amount of any damages and prejudgment interest actually paid to the class."],[0,"(7) Disclosure of settlement terms to class members"],[1,"Any proposed or final settlement agreement that is published or otherwise disseminated to the class shall include each of the following statements, along with a cover page summarizing the information contained in such statements:"],[0,"(A) Statement of plaintiff recovery"],[2,"The amount of the settlement proposed to be distributed to the parties to the action, determined in the aggregate and on an average per share basis."],[0,"(B) Statement of potential outcome of case"],[0,"(i) Agreement on amount of damages"],[3,"If the settling parties agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement concerning the average amount of such potential damages per share."],[0,"(ii) Disagreement on amount of damages"],[3,"If the parties do not agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement from each settling party concerning the issue or issues on which the parties disagree."],[0,"(iii) Inadmissibility for certain purposes"],[3,"A statement made in accordance with clause (i) or (ii) concerning the amount of damages shall not be admissible in any Federal or State judicial action or administrative proceeding, other than an action or proceeding arising out of such statement."],[0,"(C) Statement of attorneys' fees or costs sought"],[2,"If any of the settling parties or their counsel intend to apply to the court for an award of attorneys' fees or costs from any fund established as part of the settlement, a statement indicating which parties or counsel intend to make such an application, the amount of fees and costs that will be sought (including the amount of such fees and costs determined on an average per share basis), and a brief explanation supporting the fees and costs sought. Such information shall be clearly summarized on the cover page of any notice to a party of any proposed or final settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-4?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 38, 18, 32, 36, 33, 37","2":"37, 40, 45, 38, 38, 38, 37, 40, 45, 38, 38, 38","3":"16, 28","4":"13, 14, 19, 5, 6, 14, 10"},"q":[{"src":"brief","b":0,"text":"specify each statement alleged to have been misleading","cite":"15 U.S.C. § 78u-4(b)(1)"},{"src":"brief","b":0,"text":"specify each statement alleged to have been misleading [and] the reason or reasons why the statement is misleading.","cite":"15 U.S.C. § 78u-4(b)(1)"},{"src":"brief","b":2,"text":"the reason or reasons why the statement is misleading.","cite":"15 U.S.C. § 78u-4(b)(1)"},{"src":"brief","b":2,"text":"a covered person ‘knowingly commits a violation of the securities laws.’","cite":"15 U.S.C. § 78u-4"},{"src":"brief","b":3,"text":"specify each statement alleged to have been misleading,","cite":"15 U.S.C. 78u-4(b)(1)"},{"src":"brief","b":3,"text":"with particularity facts giving rise to a strong inference that the defendant acted with the required state of mind.","cite":"15 U.S.C. 78u-4(b)(2)(A)"},{"src":"brief","b":4,"text":"the reason or reasons why the statement is misleading.","cite":"15 U.S.C. §78u-4(b)(1)"}]},{"t":"usc","label":"18 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/18/1350","subs":["(b)"],"stext":{"head":"§1350. Failure of corporate officers to certify financial reports","paras":[[0,"(a) Certification of Periodic Financial Reports.—Each periodic report containing financial statements filed by an issuer with the Securities Exchange Commission pursuant to section 13(a) or 15(d) of the Securities Exchange Act of 1934 (15 U.S.C. 78m(a) or 78o(d)) shall be accompanied by a written statement by the chief executive officer and chief financial officer (or equivalent thereof) of the issuer."],[0,"(b) Content.—The statement required under subsection (a) shall certify that the periodic report containing the financial statements fully complies with the requirements of section 13(a) or 15(d) of the Securities Exchange Act pf 1 1934 (15 U.S.C. 78m or 78o(d)) and that information contained in the periodic report fairly presents, in all material respects, the financial condition and results of operations of the issuer."],[0,"(c) Criminal Penalties.—Whoever—"],[1,"(1) certifies any statement as set forth in subsections (a) and (b) of this section knowing that the periodic report accompanying the statement does not comport with all the requirements set forth in this section shall be fined not more than $1,000,000 or imprisoned not more than 10 years, or both; or"],[1,"(2) willfully certifies any statement as set forth in subsections (a) and (b) of this section knowing that the periodic report accompanying the statement does not comport with all the requirements set forth in this section shall be fined not more than $5,000,000, or imprisoned not more than 20 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1350?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 35","2":"23, 39, 17, 39","3":"10","4":"15"},"q":[{"src":"brief","b":0,"text":"fully complies with the requirements of section 13(a).","cite":"18 U.S.C. § 1350"},{"src":"brief","b":2,"text":"fully complies with the requirements of section 13(a) . . . of the [Exchange] Act.","cite":"18 U.S.C. § 1350(b)"},{"src":"brief","b":4,"text":"fully complies with the requirements of section 13(a).","cite":"18 U.S.C. §1350"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. pt. 210","url":"https://www.ecfr.gov/current/title-17/part-210","by":{"0":"9"}},{"t":"reg","label":"17 C.F.R. pt. 229","url":"https://www.ecfr.gov/current/title-17/part-229","by":{"0":"9"}},{"t":"reg","label":"17 C.F.R. § 229.303","url":"https://www.ecfr.gov/current/title-17/section-229.303","subs":["(a)(3)(ii)","(b)(2)(ii)"],"by":{"0":"4, 9, 10, 3, 10, 42"},"q":[{"src":"brief","b":0,"text":"[d]escribe any known trends or uncertainties that have had or that the registrant reasonably expects will have a material favorable or unfavorable impact on net sales or revenues or income from continuing operations.","cite":"17 C.F.R. § 229.303(a)(3)(ii)"},{"src":"brief","b":0,"text":"any known trends or uncertainties that have had or that are reasonably likely to have a material favorable or unfavorable impact on net sales or revenues or income from continuing operations.","cite":"17 C.F.R. § 229.303(b)(2)(ii)"}]},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","subs":["(a)","(b)","(c)"],"by":{"0":"1, 2, 4, 5, 16, 17, 21, 22, 24, 26, 28, 7, 23, 1, 2, 7, 16, 21, 22, 26, 7, 23","4":"1, 4, 9, 10, 11, 12, 13, 1, 4, 5, 6, 7, 8, 14, 1, 4, 9, 10, 11, 12, 13"},"q":[{"src":"brief","b":0,"text":"[t]o make any untrue statement of a material fact or to omit to state a material fact necessary in order to make the statements made * * * not misleading.","cite":"17 C.F.R. § 240.10b-5(b)"},{"src":"brief","b":0,"text":"omit[ted] to state a material fact.","cite":"17 C.F.R. § 240.10b-5(b)"}]},{"t":"reg","label":"OTHER AUTHORITIES Adoption of Disclosure Regulation & Amendments of Disclosure Forms and Rules, Securities Act Release No. 5893, 42 Fed. Reg. 65,554","url":"https://www.govinfo.gov/link/fr/42/65554","by":{"0":"9"}},{"t":"reg","label":"Management’s Discussion & Analysis of Financial Condition & Results of Operations, Exchange Act Release No. 26831, 54 Fed. Reg. 22,427","url":"https://www.govinfo.gov/link/fr/54/22427","by":{"0":"9, 41, 42, 43","2":"5-6, 43","3":"4, 27"}},{"t":"reg","label":"SEC Guidance Regarding Management’s Discussion & Analysis of Financial Condition & Results of Operations, Exchange Act Release No. 48960, 68 Fed. Reg. 75,056","url":"https://www.govinfo.gov/link/fr/68/75056","by":{"0":"44","2":"6","3":"5"}},{"t":"case","label":"Dura Pharmaceuticals, Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"by":{"1":"2","3":"3"}},{"t":"case","label":"Hutchison v. Deutsche Bank Securities Inc.","cite":"647 F.3d 479","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/647/479/","by":{"1":"8"}},{"t":"case","label":"Lawrence v. Chater","cite":"516 U.S. 163","y":1996,"id":"1995/94-9323","sc":1,"by":{"1":"9"}},{"t":"case","label":"Rombach v. Chang","cite":"355 F.3d 164","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/355/164/","by":{"1":"9"}},{"t":"case","label":"Stadnick v. Vivint Solar, Inc.","cite":"861 F.3d 31","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/861/31/","by":{"1":"8"}},{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"by":{"2":"18"}},{"t":"case","label":"Amgen Inc. v. Connecticut Ret. Plans & Tr. Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"by":{"2":"3, 4","3":"33"},"q":[{"src":"brief","b":3,"text":"meritorious private actions to enforce federal antifraud securities laws are an essential supplement to criminal prosecutions and civil enforcement actions.","cite":"568 U.S. 455, 478"}]},{"t":"case","label":"Direct Benefits, LLC v. TAC Fin., Inc.","cite":"2020 WL 2769982","y":2020,"court":"D. Md. May 28","by":{"2":"46"}},{"t":"case","label":"Durland v. United States","cite":"161 U.S. 306","y":1896,"id":"scdb/1895-139","sc":1,"by":{"2":"22"}},{"t":"case","label":"El Paso Nat. Gas Co. v. Neztsosie","cite":"526 U.S. 473","y":1999,"id":"1998/98-6","sc":1,"by":{"2":"48"},"q":[{"src":"brief","b":2,"text":"with a view either to enlarging [its] own rights thereunder or of lessening the rights of [its] adversary.","cite":"526 U.S. 473, 479"}]},{"t":"case","label":"Ferber v. Travelers Corp.","cite":"802 F. Supp. 698","y":1992,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp./802/698/","by":{"2":"36"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"by":{"2":"48"}},{"t":"case","label":"Goldsmith v. Rawl","cite":"755 F. Supp. 96","y":1991,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./755/96/","by":{"2":"46"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"by":{"2":"31, 35-36","3":"29, 30, 32, 33","4":"12"},"q":[{"src":"brief","b":3,"text":"maintains the action’s original legal scope.","cite":"573 U.S. 258, 275"},{"src":"brief","b":3,"text":"who themselves had not made any material, public misrepresentation.","cite":"573 U.S. at 275"},{"src":"brief","b":4,"text":"it does not alter the elements of the Rule 10b-5 cause of action and thus maintains the action’s original legal scope.","cite":"573 U.S. 258, 275"},{"src":"argument","who":"Chief Justice Roberts","text":"Chief Justice, I actually think that this issue is exactly like the issue you've -- your opinion faces -- faced in Halliburton. In Halliburton, the -- there was an established element of reliance, and the Court said that you can point to a different way of satisfying an established element after the PSLRA."},{"src":"argument","who":"Chief Justice Roberts","text":"We're just saying that this fits within the half-truth theory, just like in -- just like you said in Halliburton the basic presumption of reliance fits within the long-settled element of reliance."}]},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"by":{"2":"30-31","3":"31"},"q":[{"src":"brief","b":2,"text":"is virtually absolute, even for innocent misstatements.","cite":"459 U.S. 375, 382"},{"src":"brief","b":3,"text":"conduct [that] may also be actionable under § 11.","cite":"459 U.S. at 382"},{"src":"brief","b":3,"text":"he must prove that the defendant acted with scienter.","cite":"459 U.S. at 382"}]},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"by":{"2":"49"},"q":[{"src":"brief","b":2,"text":"[a] question which is merely complementary or related to the question presented in the petition for certiorari is not fairly included therein.","cite":"510 U.S. 27, 31-32"}]},{"t":"case","label":"Junius Constr. Corp. v. Cohen","cite":"178 N.E. 672","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./178/672/","by":{"2":"22","3":"15, 17, 18"},"q":[{"src":"brief","b":3,"text":"[t]he enumeration of two streets, described as unopened but projected, was a tacit representation that the land to be conveyed was subject to no others.","cite":"178 N.E. at 674"},{"src":"argument","who":"Ms. Coberly","text":"And so the classic example that this Court has discussed in Escobar is taken from Justice Cardozo in Junius Construction, and that's two streets intersect and if a third also exists but is omitted, then the statement about the two streets might be misleading by omission."},{"src":"argument","who":"Ms. Coberly","text":"So we already have the classic example, again, from Justice Cardozo in -- in Junius Construction of the two roads and the one road. So the analogy here would be, if the complaint had identified a specific statement of certain forward-looking trends that were going to have an impact and it left out this forward-looking trend that was going to have an impact, the plaintiff might be able to plead the statement requirement by identifying that specific statement."}]},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"by":{"2":"47"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"2":"22"}},{"t":"case","label":"Republic of Argentina v. NML Cap., Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"by":{"2":"49"}},{"t":"case","label":"SEC v. Capital Gains Rsch. Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"2":"2, 46"},"q":[{"src":"brief","b":2,"text":"was to substitute a philosophy of full disclosure for the philosophy of caveat emptor and thus to achieve a high standard of business ethics in the securities industry.","cite":"375 U.S. at 186"}]},{"t":"case","label":"SEC v. Das","cite":"2010 WL 4615336","y":2010,"court":"D. Neb. Nov. 4","by":{"2":"41"}},{"t":"case","label":"SEC v. Kovzan","cite":"807 F. Supp. 2d 1024","y":2011,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/807/1024/","by":{"2":"41"}},{"t":"case","label":"SEC v. Zandford","cite":"535 U.S. 813","y":2002,"id":"2001/01-147","sc":1,"by":{"2":"2, 24, 25, 30, 47","3":"2, 24","4":"10"},"q":[{"src":"brief","b":2,"text":"is coextensive with the coverage of § 10(b).","cite":"535 U.S. at 816 n.1"},{"src":"brief","b":3,"text":"Rule 10b-5 is coextensive with the coverage of § 10(b).","cite":"535 U.S. 813, 816 n.1"}]},{"t":"case","label":"Shaw v. Digital Equip. Corp.","cite":"82 F.3d 1194","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/82/1194/","by":{"2":"36-37","4":"6"}},{"t":"case","label":"Snellink v. Gulf Res., Inc.","cite":"870 F. Supp. 2d 930","y":2012,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/870/930/","by":{"2":"46"}},{"t":"case","label":"Thompson v. Western States Med. Ctr.","cite":"535 U.S. 357","y":2002,"id":"2001/01-344","sc":1,"by":{"2":"49"}},{"t":"case","label":"Trans World Airlines, Inc. v. Thurston","cite":"469 U.S. 111","y":1985,"id":"1984/83-997","sc":1,"by":{"2":"49"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"2":"16"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"by":{"2":"34"}},{"t":"case","label":"Wharf (Holdings) Ltd. v. United Int’l Holdings, Inc.","cite":"532 U.S. 588","y":2001,"id":"2000/00-347","sc":1,"by":{"2":"21, 25, 36, 44","3":"30","4":"10"},"q":[{"src":"brief","b":2,"text":"[their] concern[s] ha[ve] proved serious as a practical matter in the past.","cite":"532 U.S. at 597"}]},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"2":"49"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"2":"14, 22, 39","3":"11"}},{"t":"usc","label":"15 U.S.C. § 7241","url":"https://www.law.cornell.edu/uscode/text/15/7241","subs":["(a)(2)"],"by":{"2":"19","3":"10"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"2":"2, 11-12, 14, 27, 32-34"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)"],"by":{"2":"34, 14, 31-32, 14, 32","4":"6"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"2":"1-2, 4, 11-13, 16, 26, 31, 36, 45-46","3":"3"}},{"t":"reg","label":"Concept Release on Management’s Discussion and Analysis of Financial Condition and Operations, 52 Fed. Reg. 13,715","url":"https://www.govinfo.gov/link/fr/52/13715","by":{"2":"5"}},{"t":"reg","label":"Management’s Discussion and Analysis, Selected Financial Data, and Supplementary Financial Information, 86 Fed. Reg. 2080","url":"https://www.govinfo.gov/link/fr/86/2080","by":{"2":"7","3":"4, 27"}},{"t":"reg","label":"Selective Disclosure and Insider Trading, 65 Fed. Reg. 51,716","url":"https://www.govinfo.gov/link/fr/65/51716","by":{"2":"41","3":"25"}},{"t":"case","label":"Br. for the United States as Amicus Curiae Supporting Respondents, Leidos, Inc. v. Indiana Pub. Ret. Sys.","cite":"137 S. Ct. 1395","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/1395/","sc":1,"by":{"2":"23, 41"}},{"t":"case","label":"Pl. SEC’s Bench Mem. in Opp. to Def. Conaway’s Mot. for J. as a Matter of Law, SEC v. Conaway","cite":"698 F. Supp. 2d 771","y":2010,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/698/771/","by":{"2":"41","3":"25"}},{"t":"case","label":"Fischman v. Raytheon Mfg. Co.","cite":"188 F.2d 783","y":1951,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/188/783/","by":{"3":"21"},"q":[{"src":"brief","b":3,"text":"designed to protect investors even when there is no fraud, would afford a shelter or sanctuary for those who defraud investors.","cite":"188 F.2d 783, 787"}]},{"t":"case","label":"Gallagher v. Abbott Labs.","cite":"269 F.3d 806","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/269/806/","by":{"3":"19"}},{"t":"case","label":"Glazer v. Dress Barn, Inc.","cite":"873 A.2d 929","y":2005,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/873/929/","by":{"3":"19"}},{"t":"case","label":"Leidos, Inc. v. Indiana Pub. Ret. Sys.","cite":"138 S. Ct. 2670","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2670/","sc":1,"by":{"3":"16"}},{"t":"case","label":"Lindner Fund, Inc. v. Waldbaum, Inc.","cite":"624 N.E.2d 160","y":1993,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/624/160/","by":{"3":"19"}},{"t":"case","label":"MBIA Ins. Corp. v. Royal Indem. Co.","cite":"426 F.3d 204","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/426/204/","by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"is well known that the federal securities laws provide broader fraud protection than the common law, having been enacted in response to the common law’s perceived failure at stamping out fraud in the securities markets.","cite":"426 F.3d 204, 218"}]},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"by":{"3":"28"}},{"t":"case","label":"Rodopoulos v. Sam Piki Enters., Inc.","cite":"570 So.2d 661","y":1990,"court":"Ala.","url":"https://www.courtlistener.com/c/So.2d/570/661/","by":{"3":"19"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(b)(1)(A)"],"by":{"3":"3"},"q":[{"src":"brief","b":3,"text":"the organization, financial structure, and nature of the business,","cite":"15 U.S.C. 78l(b)(1)(A)"}]},{"t":"reg","label":"7 Fed. Reg. 3799","url":"https://www.govinfo.gov/link/fr/7/3799","by":{"3":"29"}},{"t":"reg","label":"47 Fed. Reg. 11,474","url":"https://www.govinfo.gov/link/fr/47/11474","by":{"3":"4"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"4":"8"},"q":[{"src":"brief","b":4,"text":"where Congress includes particular language in one section of a statute but omits it in another * * *, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"}]},{"t":"usc","label":"15 U.S.C. § 78u-5","url":"https://www.law.cornell.edu/uscode/text/15/78u-5","subs":["(i)(1)(C)"],"by":{"4":"19"},"q":[{"src":"brief","b":4,"text":"contained in a discussion and analysis of financial condition * * * included pursuant to the rules and regulations of the Commission.","cite":"15 U.S.C. §78u-5(i)(1)(C)"}]}]};